test('useSelector returns initial slice', () => {
  const store = createReduxStore(
    (s: { x: number }, _: any) => s,
    { x: 42 }
  );
  const { result } = renderHook(() => store.useSelector(s => s.x));
  expect(result.current).toBe(42);
});

test('dispatch updates state and selector re-renders', () => {
  const store = createReduxStore(
    (s: { n: number }, a: { type: string }) =>
      a.type === 'INC' ? { n: s.n + 1 } : s,
    { n: 0 }
  );
  const { result } = renderHook(() => store.useSelector(s => s.n));
  act(() => store.dispatch({ type: 'INC' }));
  expect(result.current).toBe(1);
});

test('dispatch is accessible outside component', () => {
  const store = createReduxStore(
    (s: { v: number }, a: { type: string; v?: number }) =>
      a.type === 'SET' ? { v: a.v! } : s,
    { v: 0 }
  );
  act(() => store.dispatch({ type: 'SET', v: 55 }));
  const { result } = renderHook(() => store.useSelector(s => s.v));
  expect(result.current).toBe(55);
});

test('multiple selectors work independently', () => {
  const store = createReduxStore(
    (s: { a: number; b: number }, act: { type: string }) =>
      act.type === 'INC_A' ? { ...s, a: s.a + 1 } : s,
    { a: 0, b: 10 }
  );
  const { result: ra } = renderHook(() => store.useSelector(s => s.a));
  const { result: rb } = renderHook(() => store.useSelector(s => s.b));
  act(() => store.dispatch({ type: 'INC_A' }));
  expect(ra.current).toBe(1);
  expect(rb.current).toBe(10);
});

